"""Build the M1 viewer from the retained checkpoint shell, revised runtime code, and packed sky data.

The M1 shell changes are applied explicitly at build time so this progress commit can remain
source-first without retaining another multi-megabyte generated HTML file.
"""
from pathlib import Path
import base64,hashlib
ROOT=Path(__file__).resolve().parent
PATCHES=[('<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><title>Open Moon — Shoreline</title><meta name="description" content="An explorable shoreline in the long lunar light. Three.js, inherited atmospheric data, and a prescribed local weather episode."><style>\n','<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><title>Open Moon — Shoreline M1</title><meta name="description" content="An explorable shoreline in the long lunar light. Three.js, inherited atmospheric data, and a prescribed local weather episode."><style>\n'),('@media(prefers-reduced-motion:reduce){#loader-bar{animation:none}#panel{transition:none}}\n','@media(prefers-reduced-motion:reduce){#loader-bar{animation:none}#panel{transition:none}}\n@media(max-width:900px){.actions #shore-edge,.actions #m1-motion,.actions #snapshot,.actions #sound{display:none}}\n\n/* Keep the reference caption out of the control strip. */\n.viewport-label{display:none}\n'),('<div class="top interface"><div class="identity glass"><div class="line"><span class="brand">OPEN MOON</span><span class="separator">/</span><span class="eyebrow">03</span></div><div id="place">Shoreline</div></div><div class="actions"><button id="sound" title="Enable spatial sound">Sound off</button><button id="snapshot" title="Save the current scenario state">Save state</button><button id="hide" title="Hide controls · H">Hide UI</button><button id="help-toggle" title="Controls and interpretation">Help</button><button id="panel-toggle">Conditions</button></div></div>\n<div class="viewport-label interface">A walk through the long light</div>\n','<div class="top interface"><div class="identity glass"><div class="line"><span class="brand">OPEN MOON</span><span class="separator">/</span><span class="eyebrow">M1</span></div><div id="place">Shoreline</div></div><div class="actions"><button id="m1-benchmark" title="Restore the repeatable clear-noon camera">M1 noon</button><button id="shore-edge">Water’s edge</button><button id="m1-motion">Resume motion</button><button id="sound" title="Enable spatial sound">Sound off</button><button id="snapshot" title="Save the current scenario state">Save state</button><button id="hide" title="Hide controls · H">Hide UI</button><button id="help-toggle" title="Controls and interpretation">Help</button><button id="panel-toggle">Conditions</button></div></div>\n<div class="viewport-label interface">Shoreline · clear-noon study</div>\n'),('<div class="panel-row"><label for="quality">Graphics</label><select id="quality"><option value="economy">Economy</option><option value="balanced" selected>Balanced</option><option value="high">High</option></select></div><div class="panel-row"><label for="lamp">Shelter light</label><input type="checkbox" id="lamp"></div>\n<hr class="rule"><h3>Keep the experience</h3><button class="wide" id="save-offline">Save self-contained offline copy</button><p>The first opening loads a pinned, hash-checked Three.js library. The saved offline HTML includes that library, all sky data, scene code, and procedural assets.</p>\n','<div class="panel-row"><label for="quality">Graphics</label><select id="quality"><option value="economy">Economy</option><option value="balanced" selected>Balanced</option><option value="high">High</option></select></div><div class="panel-row"><label for="white-balance">Camera colour</label><select id="white-balance"><option value="1">Daylight balanced</option><option value="0">Fixed D65</option></select></div><div class="panel-row"><label for="lamp">Shelter light</label><input type="checkbox" id="lamp"></div>\n<hr class="rule"><h3>Keep the experience</h3><button class="wide" id="save-offline">Save self-contained offline copy</button><p>This build embeds the pinned, hash-checked Three.js library, sky data, scene code, and procedural assets. It can be opened offline; a WebGL2-capable browser is required.</p>\n'),('<details><summary>Sources and licensing</summary><p>Three.js r180, MIT license. Rendering uses its scene graph, mesh instancing, PBR materials, shadows, and environment-map filtering.</p><p>The inherited sky inputs and their hashes are preserved in the source package. Their methods cite Bruneton’s precomputed atmospheric-scattering work and Wyman, Sloan &amp; Shirley’s colour-matching approximations.</p><p>All new scenery and sound are generated procedurally. Full attribution is embedded below and included in LICENSES.txt.</p></details><div class="source-note">Open Moon · Immersion / Light cycle · Shoreline 03<br>Standalone build · No accounts, telemetry, or remote scene data</div>\n','<details><summary>Sources and licensing</summary><p>Three.js r180, MIT license. Rendering uses its scene graph, mesh instancing, PBR materials, shadows, and environment-map filtering.</p><p>The inherited sky inputs and their hashes are preserved in the source package. Their methods cite Bruneton’s precomputed atmospheric-scattering work and Wyman, Sloan &amp; Shirley’s colour-matching approximations.</p><p>All new scenery and sound are generated procedurally. Full attribution is embedded below and included in LICENSES.txt.</p></details><div class="source-note">Open Moon · Immersion / Light cycle · Shoreline M1 review 01<br>Standalone build · No accounts, telemetry, or remote scene data</div>\n'),('<dialog id="help"><div class="eyebrow">OPEN MOON / SHORELINE</div><h1>Explore the shoreline</h1><p>Walk through the light, step under the rain shelter, and watch the landscape stay wet after the sky clears.</p><div class="help-grid"><div><strong>Look and walk</strong>Drag to look. Use W A S D to walk, Shift to move faster, and Space for a small ballistic hop. On touch screens use the left joystick.</div><div><strong>Visit four places</strong>Shoreline, shelter, woodland path, and overlook are quick jumps within the same three-dimensional scene.</div><div><strong>Compare conditions</strong>Hold noon fixed and choose Rain, Clearing, or After rain in Conditions. The month slider changes the Sun separately.</div><div><strong>Listen and watch</strong>Sound follows the shore, trees, and shelter. Live mode advances environmental time; Optical study holds the scenario for inspection.</div></div><p class="notice">The sky is inherited model output. The terrain and weather episode are explicit illustrative scenarios. This build’s complete WebGL path awaits browser verification; the source package records the checks actually performed.</p><button id="help-close" class="primary">Enter the scene</button></dialog>\n','<dialog id="help"><div class="eyebrow">OPEN MOON / SHORELINE</div><h1>Explore the shoreline</h1><p>The opening view is a repeatable, paused clear-noon reference. Drag to look, use W A S D to move, and choose M1 noon to restore the reference camera and lighting.</p><div class="help-grid"><div><strong>Look and walk</strong>Drag to look. Use W A S D to walk, Shift to move faster, and Space for a small ballistic hop. On touch screens use the left joystick.</div><div><strong>Visit four places</strong>Shoreline, shelter, woodland path, and overlook are quick jumps within the same three-dimensional scene.</div><div><strong>Compare conditions</strong>Hold noon fixed and choose Rain, Clearing, or After rain in Conditions. The month slider changes the Sun separately.</div><div><strong>Listen and watch</strong>Sound follows the shore, trees, and shelter. Live mode advances environmental time; Optical study holds the scenario for inspection.</div></div><p class="notice">The sky is inherited model output. The terrain and weather episode are explicit illustrative scenarios. The clear-noon view has been rendered and inspected in Chromium with software WebGL. This is an M1 review build; the source package separates numeric checks, image review, and work still pending.</p><button id="help-close" class="primary">Enter the scene</button></dialog>\n'),('<div id="boot"><div class="card"><div class="eyebrow">OPEN MOON / IMMERSION 03</div><h1>Shoreline</h1><p>A place inside the long light.</p><div id="loader-bar"></div><p id="boot-status">Opening the experience…</p><div id="boot-actions" hidden><button id="retry">Retry loading</button><label class="file-label">Use local three.cjs<input id="local-vendor" type="file" accept=".cjs,.js,text/javascript"></label><button id="boot-about">About this build</button></div><p class="source-note">Initial opening needs Three.js r180 from jsDelivr.<br>Use “Save self-contained offline copy” after it opens.</p></div></div>\n','<div id="boot"><div class="card"><div class="eyebrow">OPEN MOON / IMMERSION M1</div><h1>Shoreline</h1><p>A place inside the long light.</p><div id="loader-bar"></div><p id="boot-status">Opening the experience…</p><div id="boot-actions" hidden><button id="retry">Retry loading</button><label class="file-label">Use local three.cjs<input id="local-vendor" type="file" accept=".cjs,.js,text/javascript"></label><button id="boot-about">About this build</button></div><p class="source-note">Three.js r180 and calculated sky data are embedded.<br>The opening scene is the frozen clear-noon reference.</p></div></div>\n'),('<script>__CORE__</script><script>__ATMOSPHERE__</script><script>__SCENE__</script><script>__WATER__</script><script>__AUDIO__</script><script>__APP__</script><script>__LOADER__</script>\n','<script>__CORE__</script><script>__ATMOSPHERE__</script><script>__MATERIALS__</script>\n<script>__SCENE__</script><script>__WATER__</script><script>__AUDIO__</script><script>__APP__</script><script>__LOADER__</script>\n')]
html=(ROOT/'index.template.html').read_text()
if '__MATERIALS__' not in html:
 for old,new in PATCHES:
    if old not in html: raise ValueError('M1 template patch no longer matches checkpoint shell')
    html=html.replace(old,new,1)
html=html.replace('__SKY_DATA__',(ROOT/'data/atmosphere.json').read_text())
vendor=ROOT/'vendor/three.cjs'
if vendor.exists():
 b=vendor.read_bytes(); h=hashlib.sha1(b'blob '+str(len(b)).encode()+b'\0'+b).hexdigest()
 if h!='ca4833532c363b72477b2e8a6f47cc0e2fc7b09a': raise ValueError('Three.js library hash mismatch')
 encoded=base64.b64encode(b).decode()
else: encoded=''
html=html.replace('__THREE_VENDOR__',encoded)
for name in ['core','atmosphere','materials','scene','water','audio','app','loader']:
 html=html.replace('__'+name.upper()+'__',(ROOT/'src'/f'{name}.js').read_text().replace('</script','<\\/script'))
out=ROOT/'Open_Moon_Shoreline.html';out.write_text(html)
print(f'{out.name}: {out.stat().st_size:,} bytes; dependency embedded: {vendor.exists()}')
